<script setup>
import {ref} from 'vue';
import {requestJSON} from './sceneClient';
import {validateCustomTask} from './customTasks';
const props=defineProps({scene:Object,metadata:Object});const emit=defineEmits(['created']);const busy=ref(false),message=ref(''),error=ref('');
const draft=ref({well_id:props.metadata.context.facility_access.tasks[0]?.well_id??'',depot_id:props.metadata.context.facility_access.depots[0]?.depot_id??'',priority:1,earliest_start_s:0,latest_stop_s:86400,unload_duration_s:30,install_duration_s:60,pump_duration_s:3600,extraction_rate_m3_day:1});
async function create(){busy.value=true;error.value='';message.value='';try{const entry=await requestJSON(`/api/v1/scene-catalog/${props.scene.scenario_id}/versions/${props.scene.scenario_version}/tasks`,{body:{manifest_sha256:props.scene.manifest_sha256,...draft.value}});await validateCustomTask(entry,props.metadata);message.value=`已创建 ${entry.snapshot.id}，尚未选择或执行；创建不保证调度可行。`;emit('created',entry);}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><details aria-label="创建部署任务"><summary>创建部署任务（已有操作点）</summary><p>仅选择本版本已验证操作点与基地；固定1台pump及pump-install技能。不新增坐标、井或道路，不产生返程。</p><label>目标操作井 <select aria-label="新任务操作井" v-model="draft.well_id"><option v-for="t in metadata.context.facility_access.tasks" :key="t.well_id" :value="t.well_id">{{t.well_id}} · cell {{t.cell_id}} · synthetic操作关联</option></select></label><label>供应基地 <select aria-label="新任务基地" v-model="draft.depot_id"><option v-for="d in metadata.context.facility_access.depots" :key="d.depot_id" :value="d.depot_id">{{d.depot_id}}</option></select></label><label v-for="(label,key) in {priority:'优先级',earliest_start_s:'最早开始秒',latest_stop_s:'最晚停止秒',unload_duration_s:'卸载秒',install_duration_s:'安装秒',pump_duration_s:'抽水持续秒',extraction_rate_m3_day:'抽水强度m³/day'}" :key="key">{{label}} <input type="number" :aria-label="'新任务 '+label" v-model.number="draft[key]"></label><button :disabled="busy" @click="create">保存新增任务</button><p v-if="message" aria-label="创建任务结果">{{message}}</p><p v-if="error" role="alert">{{error}}</p></details></template>
